mapper.select:
SELECT ID AS id, USERNAME AS username, PASSWORD AS password, NAME AS name,
       EMAIL AS email, PHONE AS phone, ROLE AS role
FROM MB_USER WHERE USERNAME = #{username}

mapper.update:
UPDATE MB_USER
SET NAME = #{name}, EMAIL = #{email}, PHONE = #{phone}, UPDATED_AT = SYSTIMESTAMP
WHERE ID = #{id}

UPDATE MB_RESERVATION
SET CUSTOMER_NAME = #{name}, CUSTOMER_EMAIL = #{email}, CUSTOMER_PHONE = #{phone}, UPDATED_AT = SYSTIMESTAMP
WHERE CUSTOMER_ID = #{id}
